import type { DomainMessages, Localized } from './types'

function withLocation(copy: Localized): Localized {
  return { 'zh-CN': `${copy['zh-CN']}\n位置：{path}`, 'zh-TW': `${copy['zh-TW']}\n位置：{path}`, en: `${copy.en}\nLocation: {path}`, ko: `${copy.ko}\n위치: {path}`, ja: `${copy.ja}\n場所：{path}`, de: `${copy.de}\nPfad: {path}`, fr: `${copy.fr}\nEmplacement : {path}`, it: `${copy.it}\nPosizione: {path}`, 'es-ES': `${copy['es-ES']}\nUbicación: {path}`, ru: `${copy.ru}\nПуть: {path}`, pl: `${copy.pl}\nŚcieżka: {path}`, 'pt-BR': `${copy['pt-BR']}\nLocal: {path}` }
}

function withLocations(copy: Localized): Localized {
  return { 'zh-CN': `${copy['zh-CN']}\n涉及位置：\n{paths}`, 'zh-TW': `${copy['zh-TW']}\n涉及位置：\n{paths}`, en: `${copy.en}\nAffected locations:\n{paths}`, ko: `${copy.ko}\n관련 위치:\n{paths}`, ja: `${copy.ja}\n該当する場所：\n{paths}`, de: `${copy.de}\nBetroffene Pfade:\n{paths}`, fr: `${copy.fr}\nEmplacements concernés :\n{paths}`, it: `${copy.it}\nPosizioni interessate:\n{paths}`, 'es-ES': `${copy['es-ES']}\nUbicaciones afectadas:\n{paths}`, ru: `${copy.ru}\nЗатронутые пути:\n{paths}`, pl: `${copy.pl}\nŚcieżki objęte zmianą:\n{paths}`, 'pt-BR': `${copy['pt-BR']}\nLocais afetados:\n{paths}` }
}

export const modChangeInstallErrors: DomainMessages = {
  verifyInstallTarget: withLocation({ 'zh-CN': '校验变更目标失败：{reason}', 'zh-TW': '驗證變更目標失敗：{reason}', en: 'Could not verify a change target: {reason}', ko: '변경 대상을 확인하지 못했습니다: {reason}', ja: '変更対象を確認できませんでした：{reason}', de: "Änderungsziel konnte nicht geprüft werden: {reason}", fr: "Impossible de vérifier la cible d’une modification : {reason}", it: "Impossibile verificare la destinazione di una modifica: {reason}", 'es-ES': "No se ha podido verificar el destino del cambio: {reason}", ru: "Не удалось проверить цель изменения: {reason}", pl: "Nie udało się zweryfikować celu zmiany: {reason}", 'pt-BR': "Não foi possível verificar o destino da alteração: {reason}" }),
  verifyStagedFile: withLocation({ 'zh-CN': '校验待应用文件失败：{reason}', 'zh-TW': '驗證待套用檔案失敗：{reason}', en: 'Could not verify a file prepared for the change: {reason}', ko: '적용할 파일을 확인하지 못했습니다: {reason}', ja: '適用するファイルを確認できませんでした：{reason}', de: "Vorbereitete Datei konnte nicht geprüft werden: {reason}", fr: "Impossible de vérifier un fichier préparé pour la modification : {reason}", it: "Impossibile verificare un file preparato per la modifica: {reason}", 'es-ES': "No se ha podido verificar un archivo preparado para el cambio: {reason}", ru: "Не удалось проверить подготовленный файл: {reason}", pl: "Nie udało się zweryfikować pliku przygotowanego do zmiany: {reason}", 'pt-BR': "Não foi possível verificar um arquivo preparado para a alteração: {reason}" }),
  verifyInstallBackup: withLocation({ 'zh-CN': '校验变更备份失败：{reason}', 'zh-TW': '驗證變更備份失敗：{reason}', en: 'Could not verify a change backup: {reason}', ko: '변경 백업을 확인하지 못했습니다: {reason}', ja: '変更のバックアップを確認できませんでした：{reason}', de: "Sicherung der Änderung konnte nicht geprüft werden: {reason}", fr: "Impossible de vérifier une sauvegarde de la modification : {reason}", it: "Impossibile verificare una copia di backup della modifica: {reason}", 'es-ES': "No se ha podido verificar una copia de seguridad del cambio: {reason}", ru: "Не удалось проверить резервную копию для изменения: {reason}", pl: "Nie udało się zweryfikować kopii zapasowej związanej ze zmianą: {reason}", 'pt-BR': "Não foi possível verificar um backup da alteração: {reason}" }),
  verifyInstallResult: withLocation({ 'zh-CN': '校验变更结果失败：{reason}', 'zh-TW': '驗證變更結果失敗：{reason}', en: 'Could not verify the result of a change: {reason}', ko: '변경 결과를 확인하지 못했습니다: {reason}', ja: '変更結果を確認できませんでした：{reason}', de: "Ergebnis der Änderung konnte nicht geprüft werden: {reason}", fr: "Impossible de vérifier le résultat d’une modification : {reason}", it: "Impossibile verificare il risultato di una modifica: {reason}", 'es-ES': "No se ha podido verificar el resultado del cambio: {reason}", ru: "Не удалось проверить результат изменения: {reason}", pl: "Nie udało się zweryfikować wyniku zmiany: {reason}", 'pt-BR': "Não foi possível verificar o resultado da alteração: {reason}" }),
  writeInstallFile: withLocation({ 'zh-CN': '写入变更失败：{reason}', 'zh-TW': '寫入變更失敗：{reason}', en: 'Could not write a change: {reason}', ko: '변경 내용을 기록하지 못했습니다: {reason}', ja: '変更を書き込めませんでした：{reason}', de: "Änderung konnte nicht geschrieben werden: {reason}", fr: "Impossible d’écrire une modification : {reason}", it: "Impossibile scrivere la modifica: {reason}", 'es-ES': "No se ha podido escribir el cambio: {reason}", ru: "Не удалось записать изменение: {reason}", pl: "Nie udało się zapisać zmiany: {reason}", 'pt-BR': "Não foi possível gravar a alteração: {reason}" }),
  writeInstallBackup: withLocation({ 'zh-CN': '创建变更备份失败：{reason}', 'zh-TW': '建立變更備份失敗：{reason}', en: 'Could not save a change backup: {reason}', ko: '변경 백업을 저장하지 못했습니다: {reason}', ja: '変更のバックアップを保存できませんでした：{reason}', de: "Sicherung der Änderung konnte nicht gespeichert werden: {reason}", fr: "Impossible d’enregistrer une sauvegarde de la modification : {reason}", it: "Impossibile salvare una copia di backup della modifica: {reason}", 'es-ES': "No se ha podido guardar una copia de seguridad del cambio: {reason}", ru: "Не удалось сохранить резервную копию для изменения: {reason}", pl: "Nie udało się zapisać kopii zapasowej związanej ze zmianą: {reason}", 'pt-BR': "Não foi possível salvar um backup da alteração: {reason}" }),
  installRecoveryPending: { 'zh-CN': '无法确认本次变更已应用或已回滚。请保留恢复文件，关闭游戏后重启管理器。\n详细原因：{reason}', 'zh-TW': '無法確認此次變更已套用或已回復。請保留復原檔案，關閉遊戲後重新啟動管理器。\n詳細原因：{reason}', en: 'The manager could not confirm whether the changes were applied or rolled back. Keep the recovery files, close the game, and restart the manager.\nDetails: {reason}', ko: '변경이 적용되었는지 또는 되돌려졌는지 확인할 수 없습니다. 복구 파일을 보관하고 게임을 닫은 뒤 관리자를 다시 시작하세요.\n자세한 원인: {reason}', ja: '変更が適用されたか取り消されたかを確認できません。復旧用ファイルを残し、ゲームを閉じてからマネージャーを再起動してください。\n詳細：{reason}', de: "Der Manager konnte nicht bestätigen, ob die Änderungen angewendet oder zurückgerollt wurden.Behalten Sie die Wiederherstellungsdateien, schließen Sie das Spiel und starten Sie den Manager neu.\nEinzelheiten: {reason}", fr: "Le gestionnaire n'a pas pu confirmer si les modifications ont été appliquées ou retournées. Gardez les fichiers de récupération, fermez le jeu, et redémarrez le gestionnaire.\nDétails: {reason}", it: "Il manager non poteva confermare se i cambiamenti sono stati applicati o ripiegati indietro. Mantenere i file di recupero, chiudere il gioco, e riavviare il manager.\nDettagli: {reason}", 'es-ES': "El gerente no pudo confirmar si los cambios se aplicaron o se enrollaron hacia atrás. Mantenga los archivos de recuperación, cierre el juego, y reiniciar al gerente.\nDetalles: {reason}", ru: "Менеджер не смог подтвердить, были ли внесены изменения или откатывались назад.Сохранить файлы восстановления, закрыть игру и перезапустить менеджера.\nПодробности: {reason}", pl: "Menedżer nie mógł potwierdzić, czy zmiany zostały zastosowane czy cofnięte. Zachowaj pliki odzyskiwania, zamknij grę i uruchom ponownie menedżera.\nSzczegóły: {reason}", 'pt-BR': "O gerente não pôde confirmar se as alterações foram aplicadas ou roladas para trás. Mantenha os arquivos de recuperação, feche o jogo e reinicie o gerenciador.\nDetalhes: {reason}" },
  dependencyVersionUnconfirmed: { 'zh-CN': '「{subject}」需要「{dependency}」满足版本要求 {requirement}。管理器无法确认已启用的版本是否符合要求，会保留它。', 'zh-TW': '「{subject}」需要「{dependency}」符合版本要求 {requirement}。管理器無法確認已啟用的版本是否符合要求，會保留它。', en: '“{subject}” requires “{dependency}” to meet the version requirement {requirement}. The manager will keep the enabled version but could not verify that it meets this requirement.', ko: '“{subject}”에 필요한 “{dependency}”의 버전 조건은 {requirement}입니다. 활성화된 버전이 이 조건을 충족하는지 확인하지 못했으며 해당 버전을 유지합니다.', ja: '「{subject}」には「{dependency}」のバージョン条件 {requirement} があります。有効なバージョンが条件を満たすかは確認できませんでした。そのバージョンは維持されます。', de: "\"{subject}\" erfordert \"{dependency}\", um die Versionsanforderung {requirement} zu erfüllen. Der Manager behält die aktivierte Version, konnte jedoch nicht überprüfen, ob sie diese Anforderung erfüllt.", fr: "{subject}-Q exige que {dependency}-Q réponde aux exigences de la version {requirement}. Le gestionnaire conservera la version activée mais ne pourrait pas vérifier qu'elle satisfait à ces exigences.", it: "“{subject}” richiede “{dependency}” per soddisfare il requisito di versione {requirement}. Il manager manterrà la versione abilitata ma non potrà verificare che soddisfi questo requisito.", 'es-ES': "“{subject}” requiere “{dependency}” para cumplir con el requisito de la versión {requirement}. El gerente mantendrá la versión habilitada pero no pudo verificar que cumple con este requisito.", ru: "«{subject}» требует от «{dependency}» выполнения требования к версии {requirement}. Менеджер сохранит включенную версию, но не сможет проверить, соответствует ли она этому требованию.", pl: "\"{subject}\" wymaga \"{dependency}\", aby spełnić wymóg wersji {requirement}. Kierownik zachowa włączoną wersję, ale nie mógł sprawdzić, czy spełnia ten wymóg.", 'pt-BR': "“{subject}” requer “{dependency}” para atender ao requisito de versão {requirement}. O gerente manterá a versão habilitada, mas não pôde verificar que atende a esse requisito." },
  dependencyDisabledUnconfirmed: { 'zh-CN': '「{subject}」需要「{dependency}」满足版本要求 {requirement}。管理器无法确认该前置的版本或依赖，将保持停用。核对前，依赖它的功能可能无法正常运行。', 'zh-TW': '「{subject}」需要「{dependency}」符合版本要求 {requirement}。管理器無法確認該前置的版本或相依項目，將維持停用。確認前，依賴它的功能可能無法正常運作。', en: '“{subject}” requires “{dependency}” to meet the version requirement {requirement}. The manager will leave this dependency disabled because its version or requirements could not be verified. Features that depend on it may not work until these are checked.', ko: '“{subject}”에 필요한 “{dependency}”의 버전 조건은 {requirement}입니다. 버전 또는 종속성을 확인할 수 없어 비활성화 상태를 유지합니다. 확인하기 전에는 관련 기능이 정상적으로 작동하지 않을 수 있습니다.', ja: '「{subject}」には「{dependency}」のバージョン条件 {requirement} があります。この依存先のバージョンや要件を確認できなかったため、無効のままにします。確認するまで関連機能が正常に動かない場合があります。', de: "\"{subject}\" erfordert \"{dependency}\", um die Versionsanforderung {requirement} zu erfüllen. Der Manager lässt diese Abhängigkeit deaktiviert, weil ihre Version oder Anforderungen nicht verifiziert werden konnten.", fr: "« {subject} » nécessite une version de « {dependency} » qui répond à la condition {requirement}. Cette dépendance reste désactivée, car sa version ou ses prérequis n’ont pas pu être vérifiés. Les fonctionnalités qui en dépendent peuvent ne pas fonctionner tant que ces vérifications ne sont pas faites.", it: "“{subject}” richiede “{dependency}” per soddisfare il requisito di versione {requirement}. Il manager lascerà questa dipendenza disabilitata perché la sua versione o i requisiti non potrebbero essere verificati.", 'es-ES': "“{subject}” requiere “{dependency}” para cumplir con el requisito de la versión {requirement}. El gerente dejará esta dependencia desactivada porque su versión o requisitos no pueden ser verificados.", ru: "«{subject}» требует от «{dependency}» выполнить требование к версии {requirement}. Менеджер оставит эту зависимость отключенной, потому что ее версия или требования не могут быть проверены. Функции, которые зависят от нее, могут не работать, пока они не будут проверены.", pl: "\"{subject}\" wymaga \"{dependency}\" spełnienia wymogu wersji {requirement}. Kierownik pozostawi to uzależnienie wyłączone, ponieważ jego wersja lub wymagania nie mogły być zweryfikowane. Funkcje, które zależą od niego nie mogą działać dopóki nie zostaną sprawdzone.", 'pt-BR': "“{subject}” requer “{dependency}” para atender ao requisito de versão {requirement}. O gerente deixará esta dependência desativada porque sua versão ou requisitos não puderam ser verificados. Recursos que dependem dele podem não funcionar até que estes sejam verificados." },
  dependencyDeclarationsUnconfirmed: { 'zh-CN': '管理器缺少「{dependency}」当前版本的部分依赖或冲突信息，无法确认它和「{subject}」是否兼容。该前置保持原样。', 'zh-TW': '管理器缺少「{dependency}」目前版本的部分相依或衝突資訊，無法確認它與「{subject}」是否相容。該前置維持原狀。', en: 'Some dependency or conflict information for the installed version of “{dependency}” is missing. The manager could not confirm compatibility with “{subject}” and will leave this dependency unchanged.', ko: '설치된 “{dependency}” 버전의 종속성 또는 충돌 정보가 일부 없어 “{subject}”과 호환되는지 확인하지 못했습니다. 해당 종속성은 그대로 유지합니다.', ja: 'インストール済みの「{dependency}」に関する依存・競合情報が一部不足しており、「{subject}」との互換性を確認できませんでした。この依存先は変更しません。', de: "Einige Abhängigkeits- oder Konfliktinformationen für die installierte Version von \"{dependency}\" fehlen. Der Manager konnte die Kompatibilität mit \"{subject}\" nicht bestätigen und wird diese Abhängigkeit unverändert lassen.", fr: "Il manque des informations de dépendance ou de conflit pour la version installée de la version de l’option {dependency}. Le gestionnaire n'a pas pu confirmer la compatibilité avec l'option « {subject} » et laissera cette dépendance inchangée.", it: "Mancano alcune informazioni di dipendenza o di conflitto per la versione installata di “{dependency}” e il gestore non potrebbe confermare la compatibilità con “{subject}” e lascerà invariata questa dipendenza.", 'es-ES': "Falta cierta información de dependencia o conflicto para la versión instalada de “{dependency}”. El gerente no pudo confirmar la compatibilidad con “{subject}” y dejará esta dependencia sin cambios.", ru: "Некоторая информация о зависимости или конфликте для установленной версии «{dependency}» отсутствует. Менеджер не смог подтвердить совместимость с «{subject}» и оставит эту зависимость без изменений.", pl: "Brakuje niektórych informacji o zależności lub konflikcie dla zainstalowanej wersji \"{dependency}\". Kierownik nie mógł potwierdzić zgodności z \"{subject}\" i pozostawi tę zależność bez zmian.", 'pt-BR': "Falta alguma informação de dependência ou conflito para a versão instalada do “{dependency}”. O gestor não pôde confirmar a compatibilidade com o “{subject}” e deixará esta dependência inalterada." },
  ambiguousOwnership: { 'zh-CN': '管理器无法确认本次变更应修改哪些文件，已停止。请刷新列表再试。如果仍失败，请保留现有文件并提供日志。', 'zh-TW': '管理器無法確認此次變更應修改哪些檔案，已停止。請重新整理清單再試。如果仍失敗，請保留現有檔案並提供記錄。', en: 'The manager stopped because it could not determine which files to change. Refresh the list and try again. If it fails again, keep the existing files and share the log.', ko: '변경할 파일을 확인할 수 없어 작업을 중지했습니다. 목록을 새로 고친 뒤 다시 시도하세요. 또 실패하면 기존 파일을 보관하고 로그를 공유해 주세요.', ja: '変更すべきファイルを確認できなかったため、処理を止めました。一覧を更新して再試行し、再度失敗する場合は既存のファイルを残してログを共有してください。', de: "Der Manager stoppte, weil er nicht bestimmen konnte, welche Dateien geändert werden sollten. Die Liste aktualisieren und erneut versuchen. Wenn sie erneut fehlschlägt, behalten Sie die vorhandenen Dateien und teilen Sie das Protokoll.", fr: "Le gestionnaire s'est arrêté parce qu'il ne pouvait pas déterminer quels fichiers changer. Rafraîchir la liste et essayer à nouveau. Si elle échoue à nouveau, conservez les fichiers existants et partagez le journal.", it: "Il manager si è fermato perché non poteva determinare quali file cambiare. Rifiutare l'elenco e riprovare. Se non riesce di nuovo, mantenere i file esistenti e condividere il registro.", 'es-ES': "El gestor se detuvo porque no podía determinar qué archivos cambiar. Refresh la lista e inténtelo de nuevo. Si falla de nuevo, mantenga los archivos existentes y comparta el registro.", ru: "Менеджер остановился, потому что не мог определить, какие файлы изменить. Обновить список и попробовать еще раз. Если он снова выйдет из строя, сохраните существующие файлы и поделитесь журналом.", pl: "Menedżer zatrzymał się, ponieważ nie mógł określić, które pliki zmienić. Odśwież listę i spróbuj ponownie. Jeśli nie uda się ponownie, zachowaj istniejące pliki i udostępnij dziennik.", 'pt-BR': "O gestor parou porque não pôde determinar quais os ficheiros a alterar. Actualize a lista e tente novamente. Se falhar novamente, mantenha os ficheiros existentes e partilhe o registro." },
  failureWithoutDetails: { 'zh-CN': '这一步未完成，管理器没有收到具体原因。请重新生成方案。如果仍失败，请提供本次操作的日志。', 'zh-TW': '此步驟未完成，管理器沒有收到具體原因。請重新產生方案。如果仍失敗，請提供此次操作的記錄。', en: 'This step did not complete, and no details were returned. Create a new plan. If it fails again, share the log for this operation.', ko: '이 단계를 완료하지 못했고 구체적인 원인이 반환되지 않았습니다. 계획을 다시 만드세요. 또 실패하면 이 작업의 로그를 공유해 주세요.', ja: 'この手順を完了できず、詳しい原因も返されませんでした。計画を作り直し、再度失敗する場合はこの操作のログを共有してください。', de: "Dieser Schritt wurde nicht abgeschlossen und es wurden keine Details zurückgegeben. Erstelle einen neuen Plan. Wenn er erneut fehlschlägt, teile das Protokoll für diese Operation.", fr: "Cette étape n'a pas été terminée, et aucun détail n'a été retourné. Créez un nouveau plan. S'il échoue à nouveau, partagez le journal de cette opération.", it: "Questo passaggio non è stato completato, e non sono stati restituiti dettagli. Creare un nuovo piano. Se fallisce di nuovo, condividere il log per questa operazione.", 'es-ES': "Este paso no se completó, y no se devolvieron detalles. Cree un nuevo plan. Si falla de nuevo, comparta el registro para esta operación.", ru: "Этот шаг не завершился, и никаких подробностей не вернули. Создайте новый план. Если он снова провалится, поделитесь журналом для этой операции.", pl: "Ten krok nie zakończył się i nie zostały zwrócone żadne szczegóły. Utwórz nowy plan. Jeśli nie uda się ponownie, udostępnij dziennik dla tej operacji.", 'pt-BR': "Este passo não completou e nenhum detalhe foi retornado. Crie um novo plano. Se falhar novamente, compartilhe o registro para esta operação." },
  localModMultipleTargets: withLocations({ 'zh-CN': '本地安装包匹配到多份已装 MOD，无法确定该替换哪一份。请核对下面的位置。若要保留多份，请选择只包含目标 MOD 的安装包。', 'zh-TW': '本機安裝套件比對到多份已安裝 MOD，無法確定要取代哪一份。請確認下方的位置。若要保留多份，請選擇只包含目標 MOD 的安裝套件。', en: 'The local package matches multiple installed MODs, so the manager cannot select one to replace. Check the locations below. To keep the other copies, select a package containing just the target MOD.', ko: '로컬 패키지에 해당하는 설치된 MOD가 여러 개여서 교체할 대상을 결정할 수 없습니다. 아래 위치를 확인하세요. 다른 복사본을 유지하려면 대상 MOD만 포함된 패키지를 선택하세요.', ja: 'ローカルパッケージに一致するインストール済み MOD が複数あり、置き換える対象を特定できません。以下の場所を確認してください。他のコピーを残すには、対象の MOD だけが入ったパッケージを選んでください。', de: "Das lokale Paket stimmt mit mehreren installierten MODs überein, so dass der Manager keinen auswählen kann, der ersetzt werden soll. Überprüfen Sie die folgenden Speicherorte. Wählen Sie ein Paket aus, das nur den Ziel-MOD enthält.", fr: "Le paquet local correspond à plusieurs MOD installés, de sorte que le gestionnaire ne peut pas en sélectionner un à remplacer. Vérifiez les emplacements ci-dessous. Pour conserver les autres copies, sélectionnez un paquet contenant seulement le MOD cible.", it: "Il pacchetto locale corrisponde a più MOD installati, quindi il gestore non può selezionarne uno da sostituire. Controllare le posizioni sottostanti. Per mantenere le altre copie, selezionare un pacchetto contenente il MOD di destinazione.", 'es-ES': "El paquete local coincide con varios MOD instalados, por lo que el administrador no puede seleccionar uno para reemplazar. Compruebe los lugares a continuación. Para mantener las otras copias, seleccione un paquete que contiene sólo el MOD objetivo.", ru: "Локальный пакет соответствует нескольким установленным MOD, поэтому менеджер не может выбрать один для замены. Проверьте места ниже. Чтобы сохранить другие копии, выберите пакет, содержащий только целевой MOD.", pl: "Lokalny pakiet pasuje do wielu zainstalowanych MOD, więc menedżer nie może wybrać jednego do zastąpienia. Sprawdź lokalizacje poniżej. Aby zachować pozostałe kopie, wybierz pakiet zawierający tylko docelowy MOD.", 'pt-BR': "O pacote local corresponde a vários MODs instalados, de modo que o gerenciador não pode selecionar um para substituir. Verifique os locais abaixo. Para manter as outras cópias, selecione um pacote contendo apenas o MOD alvo." }),
  installPackageIdentityConflict: withLocations({ 'zh-CN': '安装包中有多份主插件（{guid}）。请换用只包含一份主插件的安装包，或联系发布者。', 'zh-TW': '安裝套件中有多份主要外掛（{guid}）。請改用只包含一份主要外掛的安裝套件，或聯絡發佈者。', en: 'The package contains multiple copies of its main plugin ({guid}). Use a package containing exactly one copy or contact the publisher.', ko: '패키지에 기본 플러그인({guid})의 복사본이 여러 개 있습니다. 복사본이 하나만 들어 있는 패키지를 사용하거나 게시자에게 문의하세요.', ja: 'パッケージに主プラグイン（{guid}）が複数含まれています。1 つだけ入ったパッケージを使用するか、配布元に問い合わせてください。', de: "Das Paket enthält mehrere Kopien seines Haupt-Plugins ({guid}), verwenden Sie ein Paket mit genau einer Kopie oder kontaktieren Sie den Publisher.", fr: "Le paquet contient plusieurs copies de son plugin principal ({guid}). Utilisez un paquet contenant exactement une copie ou contactez l'éditeur.", it: "Il pacchetto contiene più copie del suo plugin principale ({guid}). Utilizzare un pacchetto contenente esattamente una copia o contattare l'editore.", 'es-ES': "El paquete contiene múltiples copias de su plugin principal ({guid}). Use un paquete que contenga exactamente una copia o póngase en contacto con el editor.", ru: "Пакет содержит несколько копий своего основного плагина ({guid}). Используйте пакет, содержащий ровно одну копию или обратитесь к издателю.", pl: "Pakiet zawiera wiele kopii jego głównego wtyczki ({guid}). Użyj pakietu zawierającego dokładnie jedną kopię lub skontaktuj się z wydawcą.", 'pt-BR': "O pacote contém várias cópias do seu plug- in principal ({guid}). Use um pacote contendo exatamente uma cópia ou entre em contato com o editor." }),
  installPackageIdentityMissing: withLocation({ 'zh-CN': '安装包中找不到仓库源声明的主插件（{guid}）。请核对所选附件，或联系仓库源维护者。', 'zh-TW': '安裝套件中找不到來源宣告的主要外掛（{guid}）。請確認所選附件，或聯絡來源維護者。', en: 'The package does not contain the main plugin declared by the source ({guid}). Check the selected attachment or contact the repository maintainer.', ko: '패키지에서 소스가 명시한 기본 플러그인({guid})을 찾을 수 없습니다. 선택한 첨부 파일을 확인하거나 저장소 유지보수 담당자에게 문의하세요.', ja: 'パッケージに配布元が宣言した主プラグイン（{guid}）が見つかりません。選んだ添付ファイルを確認するか、配布元に問い合わせてください。', de: "Das Paket enthält nicht das von der Quelle deklarierte Haupt-Plugin ({guid}). Überprüfen Sie den ausgewählten Anhang oder kontaktieren Sie den Repository Maintainer.", fr: "Le paquet ne contient pas le plugin principal déclaré par la source ({guid}). Vérifiez la pièce jointe sélectionnée ou contactez le responsable du dépôt.", it: "Il pacchetto non contiene il plugin principale dichiarato dalla fonte ({guid}). Controllare l'allegato selezionato o contattare il manutentore del repository.", 'es-ES': "El paquete no contiene el plugin principal declarado por la fuente ({guid}). Compruebe el accesorio seleccionado o ponerse en contacto con el encargado del repositorio.", ru: "Пакет не содержит заявленного источником основного плагина ({guid}).Проверить выбранное вложение или связаться с хранителем репозитория.", pl: "Pakiet nie zawiera głównego wtyczki zadeklarowanego przez źródło ({guid}). Sprawdź wybrane załącznik lub skontaktuj się z opiekunem repozytorium.", 'pt-BR': "O pacote não contém o plug- in principal declarado pela fonte ({guid}). Verifique o anexo selecionado ou entre em contato com o mantenedor do repositório." }),
  installBundledMapPluginUnverified: withLocation({ 'zh-CN': '随包地图带有无法核实的插件，管理器已停止安装。请核对安装包，或联系发布者。', 'zh-TW': '隨套件附帶的地圖含有無法確認的外掛，管理器已停止安裝。請確認安裝套件，或聯絡發佈者。', en: 'A bundled map contains plugins the manager could not verify, so installation stopped. Check the package or contact the publisher.', ko: '동봉된 맵에 관리자 앱이 확인할 수 없는 플러그인이 있어 설치를 중지했습니다. 패키지를 확인하거나 게시자에게 문의하세요.', ja: '同梱マップに確認できないプラグインがあるため、インストールを中止しました。パッケージを確認するか、配布元に問い合わせてください。', de: "Eine gebündelte Karte enthält Plugins, die der Manager nicht überprüfen konnte, so dass die Installation gestoppt wurde. Überprüfen Sie das Paket oder kontaktieren Sie den Herausgeber.", fr: "Une carte groupée contient des plugins que le gestionnaire n'a pas pu vérifier, donc l'installation s'est arrêtée. Vérifiez le paquet ou contactez l'éditeur.", it: "Una mappa in bundle contiene plugin che il manager non poteva verificare, quindi l'installazione si è fermata. Controlla il pacchetto o contatta l'editore.", 'es-ES': "Un mapa incluido contiene plugins que el administrador no pudo verificar, por lo que la instalación se detuvo. Compruebe el paquete o ponerse en contacto con el editor.", ru: "В комплекте с картой содержатся плагины, которые менеджер не смог проверить, поэтому установка остановлена. Проверьте пакет или свяжитесь с издателем.", pl: "Związana mapa zawiera wtyczki, których kierownik nie mógł zweryfikować, więc instalacja ustała. Sprawdź pakiet lub skontaktuj się z wydawcą.", 'pt-BR': "Um mapa agrupado contém plug- ins que o gerenciador não pôde verificar, então a instalação parou. Verifique o pacote ou entre em contato com o editor." }),
  installMemberRelationConflict: withLocation({ 'zh-CN': '插件（{guid}）对应的来源给出了不同的依赖或冲突要求。请核对所选版本，或联系仓库源维护者。', 'zh-TW': '外掛（{guid}）對應的來源提供了不同的相依或衝突要求。請確認所選版本，或聯絡來源維護者。', en: 'The sources for plugin {guid} declare different requirements or conflicts. Check the selected version or contact the repository maintainer.', ko: '플러그인({guid})에 해당하는 소스마다 종속성이나 충돌 조건이 다릅니다. 선택한 버전을 확인하거나 저장소 유지보수 담당자에게 문의하세요.', ja: 'プラグイン（{guid}）の依存条件や競合条件が配布元によって異なります。選んだバージョンを確認するか、配布元に問い合わせてください。', de: "Die Quellen für das Plugin {guid} erklären unterschiedliche Anforderungen oder Konflikte. Überprüfen Sie die ausgewählte Version oder kontaktieren Sie den Repository Maintainer.", fr: "Les sources du plugin {guid} déclarent différentes exigences ou conflits. Vérifiez la version sélectionnée ou contactez le responsable du dépôt.", it: "Le fonti per il plugin {guid} dichiarano diversi requisiti o conflitti. Controllare la versione selezionata o contattare il manutentore del repository.", 'es-ES': "Las fuentes para el plugin {guid} declaran diferentes requisitos o conflictos. Compruebe la versión seleccionada o ponerse en contacto con el encargado del repositorio.", ru: "Источники для плагина {guid} декларируют различные требования или конфликты. Проверьте выбранную версию или обратитесь в службу поддержки репозитория.", pl: "Źródła wtyczki {guid} deklarują różne wymagania lub konflikty. Sprawdź wybraną wersję lub skontaktuj się z opiekunem repozytorium.", 'pt-BR': "As fontes do plugin {guid} declaram diferentes requisitos ou conflitos. Verifique a versão selecionada ou entre em contato com o mantenedor do repositório." }),
  localModSourceConflict: withLocation({ 'zh-CN': '各来源对本地安装包中的插件（{guid}）给出了不同的依赖或冲突要求。仍可继续安装，管理器会检查各来源一致的要求。其余要求尚未确认，可向发布者核对。\n相关来源：\n{sources}', 'zh-TW': '各來源對本機安裝套件中的外掛（{guid}）提供了不同的相依或衝突要求。仍可繼續安裝，管理器會檢查各來源一致的要求。其餘要求尚未確認，可向發佈者確認。\n相關來源：\n{sources}', en: 'Sources disagree on the dependencies or conflicts for plugin {guid} in this local package. You can continue installing. The manager will check the requirements shared by the sources. The remaining requirements are unconfirmed and can be checked with the publisher.\nAffected sources:\n{sources}', ko: '이 로컬 패키지에 포함된 플러그인({guid})의 종속성이나 충돌 조건이 소스마다 다릅니다. 설치를 계속할 수 있으며, 관리자는 소스가 공통으로 명시한 요구 사항을 검사합니다. 확인되지 않은 나머지 요구 사항은 게시자에게 문의하세요.\n관련 소스:\n{sources}', ja: 'このローカルパッケージ内のプラグイン（{guid}）について、配布元ごとに依存条件や競合条件が異なります。インストールは続行できます。管理アプリは配布元で一致した要件をチェックします。未確認の要件は公開者に確認できます。\n該当する配布元：\n{sources}', de: "Quellen sind sich nicht einig über die Abhängigkeiten oder Konflikte für das Plugin {guid} in diesem lokalen Paket. Sie können die Installation fortsetzen. Der Manager wird die von den Quellen geteilten Anforderungen überprüfen. Die restlichen Anforderungen sind unbestätigt und können mit dem Herausgeber überprüft werden.\nBetroffene Quellen:\n{sources}", fr: "Les sources ne sont pas d'accord sur les dépendances ou les conflits pour le plugin {guid} dans ce paquet local. Vous pouvez continuer à installer. Le gestionnaire vérifiera les exigences partagées par les sources. Les autres exigences sont non confirmées et peuvent être vérifiées auprès de l'éditeur.\nSources touchées:\n{sources}", it: "Le fonti non sono d'accordo sulle dipendenze o i conflitti per il plugin {guid} in questo pacchetto locale. È possibile continuare l'installazione. Il gestore controllerà i requisiti condivisi dalle fonti. I requisiti rimanenti sono non confermati e possono essere controllati con l'editore.\nFonti interessate:\n{sources}", 'es-ES': "Fuentes discrepan sobre las dependencias o conflictos para el plugin {guid} en este paquete local. Puede continuar instalando. El gerente comprobará los requisitos compartidos por las fuentes. Los requisitos restantes no están confirmados y pueden ser revisados con el editor.\nFuentes afectadas:\n{sources}", ru: "Источники расходятся во мнениях по поводу зависимостей или конфликтов для плагина {guid} в этом локальном пакете. Можно продолжить установку. Менеджер проверит требования, разделяемые источниками. Остальные требования неподтверждены и могут быть проверены издателем.\nПострадавшие источники:\n{sources}", pl: "Źródła nie zgadzają się co do zależności lub konfliktów dotyczących wtyczki {guid} w tym lokalnym pakiecie. Możesz kontynuować instalację. Kierownik będzie sprawdzał wymagania współdzielone przez źródła. Pozostałe wymagania są niepotwierdzone i mogą być sprawdzone przez wydawcę.\nŹródła dotknięte chorobą:\n{sources}", 'pt-BR': "As fontes discordam das dependências ou conflitos para o 'plugin' {guid} neste pacote local. Você pode continuar a instalar. O gestor irá verificar os requisitos partilhados pelas fontes. Os restantes requisitos não estão confirmados e poderão ser verificados com o editor.\nFontes afetadas:\n{sources}" }),
  installTargetIdentityConflict: { 'zh-CN': '有多份安装记录指向同一项目（{name}）。请刷新列表再试。如果仍失败，请保留现有文件和安装记录，并提供日志。', 'zh-TW': '有多份安裝記錄指向同一項目（{name}）。請重新整理清單再試。如果仍失敗，請保留現有檔案和安裝記錄並提供記錄檔。', en: 'Multiple installation records point to the same item ({name}). Refresh the list and try again. If it fails again, keep the files and installation records and share the log.', ko: '같은 항목({name})을 가리키는 설치 기록이 여러 개 있습니다. 목록을 새로 고친 뒤 다시 시도하세요. 또 실패하면 파일과 설치 기록을 보관하고 로그를 공유해 주세요.', ja: '同じ項目（{name}）を指すインストール記録が複数あります。一覧を更新して再試行し、再度失敗する場合はファイルとインストール記録を残してログを共有してください。', de: "Mehrere Installationsaufzeichnungen zeigen auf dasselbe Element ({name}). Aktualisieren Sie die Liste und versuchen Sie es erneut.", fr: "Plusieurs enregistrements d'installation pointent vers le même élément ({name}). Rafraîchir la liste et essayer à nouveau. Si elle échoue à nouveau, conservez les fichiers et les enregistrements d'installation et partagez le journal.", it: "Più registri di installazione fanno riferimento allo stesso elemento ({name}). Aggiorna l’elenco e riprova. Se il problema si ripete, conserva i file e i registri di installazione e condividi il log.", 'es-ES': "Múltiples registros de instalación apuntan al mismo elemento ({name}). Refresque la lista e inténtelo de nuevo. Si falla de nuevo, mantenga los archivos y registros de instalación y comparta el registro.", ru: "Несколько записей об установке указывают на один и тот же элемент ({name}). Обновите список и попробуйте еще раз. Если он снова выйдет из строя, сохраните файлы и записи об установке и поделитесь журналом.", pl: "Wielokrotne rekordy instalacji wskazują na ten sam element ({name}). Odśwież listę i spróbuj ponownie. Jeśli nie uda się ponownie, przechowywać pliki i rekordy instalacji i udostępniać dziennik.", 'pt-BR': "Vários registros de instalação apontam para o mesmo item ({name}). Atualizar a lista e tentar novamente. Se falhar novamente, mantenha os arquivos e registros de instalação e compartilhe o registro." },
  installTargetOwnershipUnverified: { 'zh-CN': '无法确认应该由哪条安装记录管理「{name}」。请刷新列表再试。如果仍失败，请保留现有文件并提供日志。', 'zh-TW': '無法確認應由哪一筆安裝記錄管理「{name}」。請重新整理清單再試。如果仍失敗，請保留現有檔案並提供記錄。', en: 'The manager could not verify which installation record owns “{name}”. Refresh the list and try again. If it fails again, keep the files and share the log.', ko: '어느 설치 기록에서 “{name}” 항목을 관리하는지 확인할 수 없습니다. 목록을 새로 고친 뒤 다시 시도하세요. 또 실패하면 파일을 보관하고 로그를 공유해 주세요.', ja: '「{name}」を管理するインストール記録を確認できませんでした。一覧を更新して再試行し、再度失敗する場合はファイルを残してログを共有してください。', de: "Der Manager konnte nicht überprüfen, welcher Installationsdatensatz \"{name}\" besitzt. Aktualisieren Sie die Liste und versuchen Sie es erneut.", fr: "Le gestionnaire n'a pas pu vérifier quel enregistrement d'installation est propriétaire du fichier {name}. Rafraîchir la liste et essayer à nouveau. S'il échoue à nouveau, conservez les fichiers et partagez le journal.", it: "Il manager non poteva verificare quale record di installazione possiede “{name}”. Rifiutare la lista e riprova. Se non riesce ancora, tenere i file e condividere il registro.", 'es-ES': "El gerente no pudo verificar qué registro de instalación posee “{name}”. Refresh la lista e inténtelo de nuevo. Si falla de nuevo, mantenga los archivos y comparta el registro.", ru: "Менеджер не смог проверить, какой установочной записи принадлежит «{name}». Обновите список и попробуйте еще раз. Если он снова не сработает, сохраните файлы и поделитесь журналом.", pl: "Menedżer nie mógł zweryfikować, który rekord instalacji jest właścicielem \"{name}\". Odśwież listę i spróbuj ponownie. Jeśli nie uda się ponownie, przechowywać pliki i udostępniać dziennik.", 'pt-BR': "O gerenciador não pôde verificar qual registro de instalação possui “{name}”. Atualizar a lista e tentar novamente. Se falhar novamente, mantenha os arquivos e compartilhe o registro." },
  installTargetMissing: withLocation({ 'zh-CN': '预期的安装文件已不存在，或该位置已不再是文件。请刷新列表，核对文件是否已被移动，再重试。', 'zh-TW': '預期的安裝檔案已不存在，或該位置已不再是檔案。請重新整理清單，確認檔案是否已被移動，再試一次。', en: 'The expected installed file is missing, or this location no longer points to a file. Refresh the list, check whether the file was moved, and retry.', ko: '예상한 설치 파일이 없거나 해당 위치가 더 이상 파일을 가리키지 않습니다. 목록을 새로 고치고 파일이 이동했는지 확인한 뒤 다시 시도하세요.', ja: '想定していたインストール済みファイルが存在しないか、この場所がファイルを指していません。一覧を更新し、ファイルが移動されたか確認してから再試行してください。', de: "Die erwartete installierte Datei fehlt, oder dieser Speicherort verweist nicht mehr auf eine Datei. Aktualisieren Sie die Liste, überprüfen Sie, ob die Datei verschoben wurde, und wiederholen Sie es.", fr: "Le fichier installé attendu est manquant, ou cet emplacement ne pointe plus vers un fichier. Rafraîchir la liste, vérifier si le fichier a été déplacé, et réessayer.", it: "Il file installato previsto manca, o questa posizione non punta più a un file.Rifiutare l'elenco, verificare se il file è stato spostato e riprovare.", 'es-ES': "El archivo instalado esperado está desaparecido, o esta ubicación ya no apunta a un archivo. Refresca la lista, compruebe si el archivo fue movido, y reingrese.", ru: "Ожидаемый установленный файл отсутствует, или это место больше не указывает на файл. Обновите список, проверьте, был ли файл перемещен, и повторите.", pl: "Oczekiwany zainstalowany plik jest brakujący, lub to położenie nie wskazuje już na plik. Odśwież listę, sprawdź czy plik został przeniesiony i spróbuj ponownie.", 'pt-BR': "Falta o arquivo instalado esperado, ou este local não aponta mais para um arquivo. Atualizar a lista, verificar se o arquivo foi movido e tentar novamente." }),
  // Also used to display the legacy file-ownership tag from previous versions.
  fileOwnershipConflict: withLocation({ 'zh-CN': '管理器无法确认这个位置能否安全替换。请保留现有文件，并将日志发给管理器维护者。', 'zh-TW': '管理器無法確認這個位置能否安全取代。請保留現有檔案，並將記錄傳給管理器維護者。', en: 'The manager could not verify that it is safe to replace the file at this location. Keep the existing files and send the log to the manager’s maintainers.', ko: '이 위치의 파일을 안전하게 교체할 수 있는지 확인하지 못했습니다. 기존 파일을 보관하고 관리자 앱의 유지보수 담당자에게 로그를 보내 주세요.', ja: 'この場所のファイルを安全に置き換えられるか確認できませんでした。既存のファイルを残し、ログを管理アプリのメンテナーに送ってください。', de: "Der Mod-Manager konnte nicht bestätigen, dass die Datei an diesem Pfad sicher ersetzt werden kann. Bewahren Sie die vorhandenen Dateien auf und senden Sie das Protokoll an die Betreuer des Mod-Managers.", fr: "Le gestionnaire n’a pas pu vérifier que le fichier à cet emplacement peut être remplacé sans risque. Conservez les fichiers existants et envoyez le journal à l’équipe du gestionnaire.", it: "Il gestore non ha potuto verificare se il file in questa posizione può essere sostituito in sicurezza. Conserva i file esistenti e invia il log a chi gestisce il programma.", 'es-ES': "El gestor no ha podido verificar que sea seguro sustituir el archivo en esta ubicación. Conserva los archivos existentes y envía el registro a los responsables del gestor.", ru: "Менеджер не смог подтвердить, что заменять файл по этому пути безопасно. Сохраните существующие файлы и отправьте журнал разработчикам менеджера.", pl: "Menedżer nie mógł potwierdzić, że plik w tej lokalizacji można bezpiecznie zastąpić. Zachowaj istniejące pliki i wyślij dziennik do osób opiekujących się menedżerem.", 'pt-BR': "O gerenciador não conseguiu verificar se é seguro substituir o arquivo neste local. Preserve os arquivos existentes e envie o log à equipe responsável pelo gerenciador." }),
  installTargetIsDirectory: withLocation({ 'zh-CN': '安装位置被同名文件夹占用。请先备份并移走该文件夹，再重试。', 'zh-TW': '安裝位置被同名資料夾占用。請先備份並移走該資料夾，再試一次。', en: 'A folder with the same name occupies the installation location. Back up and move that folder, then retry.', ko: '같은 이름의 폴더가 설치 위치를 차지하고 있습니다. 해당 폴더를 백업하고 옮긴 뒤 다시 시도하세요.', ja: 'インストール先に同名のフォルダーがあります。そのフォルダーをバックアップして移動し、再試行してください。', de: "Ein Ordner mit dem gleichen Namen nimmt den Installationsort ein. Sichern und verschieben Sie diesen Ordner und versuchen Sie es erneut.", fr: "Un dossier avec le même nom occupe l'emplacement d'installation. Sauvegarder et déplacer ce dossier, puis réessayer.", it: "Una cartella con lo stesso nome occupa la posizione dell'installazione.", 'es-ES': "Una carpeta con el mismo nombre ocupa la ubicación de la instalación. Retrocede y mueva esa carpeta, luego vuelva a entrar.", ru: "Папка с таким же названием занимает место установки. Назад и переместите эту папку, затем повторите попытку.", pl: "Folder o tej samej nazwie zajmuje miejsce instalacji. Backup i przenieść ten folder, a następnie spróbować ponownie.", 'pt-BR': "Uma pasta com o mesmo nome ocupa o local de instalação. Faça backup e mova essa pasta, então tente novamente." }),
  installTargetHasBothStates: withLocations({ 'zh-CN': '同一插件同时有启用和停用的副本。请先备份，核对要使用的版本，把多余的副本移出插件目录后再试。', 'zh-TW': '同一外掛同時有啟用和停用的副本。請先備份，確認要用的版本，將多餘的副本移出外掛資料夾後再試。', en: 'Both an enabled and a disabled copy of this plugin exist. Back them up, check which version to keep, and move the extra copy out of the plugins folder before retrying.', ko: '같은 플러그인의 활성화된 복사본과 비활성화된 복사본이 모두 있습니다. 백업한 뒤 사용할 버전을 확인하고 나머지를 플러그인 폴더 밖으로 옮긴 후 다시 시도하세요.', ja: '同じプラグインの有効なコピーと無効なコピーが両方あります。バックアップして残す版を確認し、余分な方をプラグインフォルダーの外に移動してから再試行してください。', de: "Es gibt sowohl eine aktivierte als auch eine deaktivierte Kopie dieses Plugins. Sichern Sie sie, überprüfen Sie, welche Version beibehalten werden soll, und verschieben Sie die zusätzliche Kopie aus dem Plugin-Ordner, bevor Sie es erneut versuchen.", fr: "Une copie activée et une copie désactivée de ce plugin existent. Sauvegardez-les, vérifiez quelle version conserver, et déplacez la copie supplémentaire hors du dossier des plugins avant de réessayer.", it: "Esiste una copia abilitata e disabilitata di questo plugin. Torna su, controlla quale versione tenere, e sposta la copia extra dalla cartella plugin prima di riprovare.", 'es-ES': "Tanto una copia habilitada como una copia deshabilitada de este plugin existen. Retrocede, compruebe qué versión guardar, y mueva la copia extra de la carpeta plugins antes de reintentar.", ru: "Существует как включенная, так и отключенная копия этого плагина. Обновите их, проверьте, какую версию сохранить, и переместите дополнительную копию из папки плагинов перед повторным использованием.", pl: "Zarówno włączone i wyłączone kopie tej wtyczki istnieją. Backup je, sprawdź, która wersja zachować, i przenieść dodatkową kopię z folderu wtyczek przed ponownym próbami.", 'pt-BR': "Existe uma cópia activa e uma cópia desactivada deste 'plugin'. Faça o backup deles, verifique qual a versão a manter e mova a cópia extra para fora da pasta 'plugins' antes de voltar a tentar." }),
  installTargetUnreadable: withLocation({ 'zh-CN': '管理器无法读取安装位置。请检查访问权限，或关闭可能占用该位置的程序后重试。', 'zh-TW': '管理器無法讀取安裝位置。請檢查存取權限，或關閉可能占用該位置的程式後再試。', en: 'The manager could not read the installation location. Check access permissions or close programs that might be using that location, then retry.', ko: '관리자 앱이 설치 위치를 읽을 수 없습니다. 접근 권한을 확인하거나 해당 위치를 사용 중일 수 있는 프로그램을 닫은 뒤 다시 시도하세요.', ja: 'インストール先を読み取れません。アクセス権を確認するか、この場所を使用していそうなアプリを閉じてから再試行してください。', de: "Der Manager konnte den Installationsort nicht lesen. Überprüfen Sie Zugriffsberechtigungen oder schließen Sie Programme, die diesen Speicherort verwenden, und versuchen Sie es dann erneut.", fr: "Le gestionnaire ne pouvait pas lire l'emplacement de l'installation. Vérifiez les permissions d'accès ou fermer les programmes qui pourraient être en utilisant cet emplacement, puis réessayer.", it: "Il manager non poteva leggere la posizione di installazione. Controllare le autorizzazioni di accesso o programmi chiudi che potrebbero essere utilizzando quella posizione, quindi riprovare.", 'es-ES': "El gerente no pudo leer la ubicación de la instalación. Compruebe los permisos de acceso o programas cercanos que podrían estar utilizando esa ubicación, y luego vuelva a entrar.", ru: "Менеджер не мог прочитать местоположение установки. Проверьте разрешения доступа или закройте программы, которые могут использовать это местоположение, а затем повторите попытку.", pl: "Menedżer nie mógł odczytać lokalizacji instalacji. Sprawdź uprawnienia dostępu lub zamknięcie programów, które mogą być wykorzystywane w tej lokalizacji, a następnie ponownie spróbować.", 'pt-BR': "O gestor não conseguiu ler a localização da instalação. Verifique as permissões de acesso ou os programas de encerramento que possam estar a usar essa localização e tente de novo." }),
  installTargetUnsafe: withLocation({ 'zh-CN': '这条安装路径未通过安全检查。请核对游戏目录，以及这条路径是否经过链接。', 'zh-TW': '此安裝路徑未通過安全檢查。請確認遊戲資料夾，以及此路徑是否經過連結。', en: 'The installation path did not pass its safety check. Verify the game folder and check whether the path passes through a link.', ko: '설치 경로가 안전 검사에 통과하지 못했습니다. 게임 폴더가 맞는지, 경로가 링크를 거치는지 확인하세요.', ja: 'インストール先のパスが安全性の確認に通りませんでした。ゲームのフォルダーが正しいか、途中にリンクがないか確認してください。', de: "Der Installationspfad hat seine Sicherheitsüberprüfung nicht bestanden. Überprüfen Sie den Spielordner und prüfen Sie, ob der Pfad durch einen Link läuft.", fr: "Le chemin d'installation n'a pas passé sa vérification de sécurité. Vérifiez le dossier de jeu et vérifiez si le chemin passe par un lien.", it: "Il percorso di installazione non ha superato il suo controllo di sicurezza. Verificare la cartella del gioco e verificare se il percorso passa attraverso un link.", 'es-ES': "La ruta de instalación no pasó su comprobación de seguridad. Verifique la carpeta del juego y compruebe si el camino pasa a través de un enlace.", ru: "Путь установки не прошел проверку безопасности.Проверить папку игры и проверить, проходит ли путь по ссылке.", pl: "Ścieżka instalacyjna nie przeszła kontroli bezpieczeństwa. Sprawdź folder gier i sprawdź, czy ścieżka przechodzi przez link.", 'pt-BR': "O caminho de instalação não passou na sua verificação de segurança. Verifique a pasta do jogo e verifique se o caminho passa através de um link." }),
  installTargetClaimed: withLocation({ 'zh-CN': '已有安装清单登记了这个位置，无法直接覆盖。请刷新 MOD 列表后再试。如果仍失败，请保留文件和安装清单，并提供日志。', 'zh-TW': '已有安裝清單登記了這個位置，無法直接覆寫。請重新整理 MOD 清單後再試。如果仍失敗，請保留檔案和安裝清單並提供記錄。', en: 'An existing installation manifest lists this location, so the manager blocked the overwrite. Refresh the MOD list and retry. If it fails again, keep the files and manifest and share the log.', ko: '기존 설치 명세에 이 위치가 기록되어 있어 덮어쓸 수 없습니다. MOD 목록을 새로 고친 뒤 다시 시도하세요. 또 실패하면 파일과 설치 명세를 보관하고 로그를 공유해 주세요.', ja: '既存のインストール記録にこの場所が登録されているため、上書きできません。MOD 一覧を更新して再試行してください。再度失敗する場合はファイルとインストール記録を残し、ログを共有してください。', de: "Ein vorhandenes Installationsmanifest beansprucht diesen Pfad. Der Mod-Manager hat das Überschreiben blockiert. Aktualisieren Sie die Mod-Liste und versuchen Sie es erneut. Wenn der Fehler erneut auftritt, bewahren Sie die Dateien und das Manifest auf und teilen Sie das Protokoll.", fr: "Un manifeste d’installation existant indique cet emplacement. Le gestionnaire a bloqué l’écrasement. Actualisez la liste des mods et réessayez. Si le problème persiste, conservez les fichiers et le manifeste, puis partagez le journal.", it: "Un manifesto di installazione esistente indica questa posizione, perciò il gestore ha bloccato la sovrascrittura. Aggiorna l’elenco dei mod e riprova. Se il problema persiste, conserva i file e il manifesto e condividi il log.", 'es-ES': "Un manifiesto de instalación existente incluye esta ubicación, por lo que el gestor ha bloqueado la sobrescritura. Actualiza la lista de mods y vuelve a intentarlo. Si el problema persiste, conserva los archivos y el manifiesto y comparte el registro.", ru: "Этот путь указан в существующем манифесте установки, поэтому менеджер заблокировал перезапись. Обновите список модов и повторите попытку. Если ошибка повторится, сохраните файлы и манифест и поделитесь журналом.", pl: "Istniejący manifest instalacji wskazuje tę lokalizację, dlatego menedżer zablokował nadpisanie. Odśwież listę modów i spróbuj ponownie. Jeśli błąd się powtórzy, zachowaj pliki i manifest oraz udostępnij dziennik.", 'pt-BR': "Um manifesto de instalação existente inclui este local, por isso o gerenciador bloqueou a substituição. Atualize a lista de mods e tente novamente. Se o erro persistir, preserve os arquivos e o manifesto e compartilhe o log." }),
  installTargetClaimedWithManifests: { 'zh-CN': '已有安装清单登记了这个位置（{path}）。具体占用清单：\n{manifests}', 'zh-TW': '已有安裝清單登記了這個位置（{path}）。具體占用清單：\n{manifests}', en: 'An existing installation manifest claims this location ({path}). Conflicting manifests:\n{manifests}', ko: '기존 설치 명세가 이 위치({path})를 사용 중입니다. 충돌하는 설치 명세:\n{manifests}', ja: '既存のインストール記録がこの場所（{path}）を使用中です。競合する記録：\n{manifests}', de: "Ein bestehendes Installationsmanifest beansprucht diesen Standort ({path}).\n{manifests}", fr: "Un manifeste d'installation existant revendique cet emplacement ({path}).\n{manifests}", it: "Un manifesto di installazione esistente sostiene questa posizione ({path}).\n{manifests}", 'es-ES': "Un manifiesto de instalación existente reclama esta ubicación ({path}). Manifiestos conflictivos:\n{manifests}", ru: "Существующий установочный манифест утверждает это местоположение ({path}). Противоречивый манифест:\n{manifests}", pl: "Istniejący manifest instalacji twierdzi, że ta lokalizacja ({path}).\n{manifests}", 'pt-BR': "Um manifesto de instalação existente reivindica esta localização ({path}). Manifestações em conflito:\n{manifests}" },
  installTargetOwned: withLocation({ 'zh-CN': '这个位置已被其他项目或本次方案中的另一项变更占用。请刷新列表，或分开安装后再试。', 'zh-TW': '這個位置已被其他項目或本次方案中的另一項變更占用。請重新整理清單，或分開安裝後再試。', en: 'Another item or a different change in this plan already uses this location. Refresh the list or try the installations separately.', ko: '다른 항목이나 현재 계획의 다른 변경이 이미 이 위치를 사용하고 있습니다. 목록을 새로 고치거나 하나씩 설치해 보세요.', ja: '別の項目か、今回の計画の別の変更がこの場所を使用しています。一覧を更新するか、インストールを分けて試してください。', de: "Ein anderes Element oder eine andere Änderung in diesem Plan verwendet bereits diesen Ort. Aktualisieren Sie die Liste oder probieren Sie die Installationen separat aus.", fr: "Un autre élément ou une modification différente de ce plan utilise déjà cet emplacement. Rafraîchir la liste ou essayer les installations séparément.", it: "Un altro elemento o un cambiamento diverso in questo piano utilizza già questa posizione. Rifiutare l'elenco o provare le installazioni separatamente.", 'es-ES': "Otro elemento o un cambio diferente en este plan ya utiliza esta ubicación. Refresque la lista o pruebe las instalaciones por separado.", ru: "Другой пункт или другое изменение в этом плане уже использует это местоположение.Обновите список или попробуйте установки отдельно.", pl: "Inny element lub inna zmiana w tym planie już używa tej lokalizacji. Odśwież listę lub spróbuj instalacji oddzielnie.", 'pt-BR': "Outro item ou uma alteração diferente neste plano já usa este local. Atualizar a lista ou tentar as instalações separadamente." }),
  installTargetUnrecognized: withLocation({ 'zh-CN': '该位置已有文件，管理器无法确认它属于这次要安装的项目。请刷新列表后重试。如果仍失败，请保留文件并提供日志。', 'zh-TW': '該位置已有檔案，管理器無法確認它屬於這次要安裝的項目。請重新整理清單後再試。如果仍失敗，請保留檔案並提供記錄。', en: 'A file already exists at this location, and the manager could not confirm that it belongs to the item being installed. Refresh the list and retry. If it fails again, keep the file and share the log.', ko: '이 위치에 파일이 이미 있지만 설치하려는 항목에 속하는지 확인하지 못했습니다. 목록을 새로 고친 뒤 다시 시도하세요. 또 실패하면 파일을 보관하고 로그를 공유해 주세요.', ja: 'この場所には既にファイルがあり、今回のインストール対象のものか確認できません。一覧を更新して再試行してください。再度失敗する場合はファイルを残し、ログを共有してください。', de: "Eine Datei existiert bereits an diesem Ort, und der Manager konnte nicht bestätigen, dass sie zu dem Element gehört, das installiert wird. die Liste aktualisieren und erneut versuchen.", fr: "Un fichier existe déjà à cet endroit, et le gestionnaire ne pouvait pas confirmer qu'il appartient à l'élément en cours d'installation. Rafraîchir la liste et réessayer. S'il échoue à nouveau, conserver le fichier et partager le journal.", it: "Un file già esiste in questa posizione, e il gestore non poteva confermare che appartiene all'elemento in fase di installazione.Rifiutare l'elenco e riprovare. Se non riesce di nuovo, mantenere il file e condividere il registro.", 'es-ES': "Un archivo ya existe en esta ubicación, y el administrador no pudo confirmar que pertenece al artículo que se está instalando. Refresque la lista y vuelva a entrar. Si falla de nuevo, mantenga el archivo y comparta el registro.", ru: "Файл уже существует в этом месте, и менеджер не мог подтвердить, что он принадлежит к установленному элементу. Обновите список и повторите. Если он снова выйдет из строя, сохраните файл и поделитесь журналом.", pl: "Plik już istnieje w tej lokalizacji, a menedżer nie mógł potwierdzić, że należy do zainstalowanego elementu. Odśwież listę i spróbuj ponownie. Jeśli nie powiedzie się ponownie, zachowaj plik i udostępnij dziennik.", 'pt-BR': "Já existe um ficheiro nesta localização, e o gestor não pôde confirmar que pertence ao item que está a ser instalado. Actualize a lista e tente de novo. Se falhar novamente, mantenha o ficheiro e partilhe o registo." }),
  installTargetNeedsVerifiedRelease: withLocation({ 'zh-CN': '该位置已有文件。安装包缺少用来确认能否覆盖旧文件的校验信息。请保留旧文件，并将日志发给管理器维护者。', 'zh-TW': '該位置已有檔案。安裝套件缺少用來確認能否覆寫舊檔案的驗證資訊。請保留舊檔案，並將記錄傳給管理器維護者。', en: 'A file already exists here. The package lacks the verification needed to confirm that it can overwrite the old file. Keep the old file and send the log to the manager’s maintainers.', ko: '이 위치에 파일이 이미 있습니다. 설치 패키지에 기존 파일을 덮어써도 되는지 확인할 검증 정보가 없습니다. 기존 파일을 보관하고 관리자 앱의 유지보수 담당자에게 로그를 보내 주세요.', ja: 'この場所には既にファイルがあります。パッケージには既存ファイルを上書きできるか確認するための検証情報がありません。既存ファイルを残し、ログを管理アプリのメンテナーに送ってください。', de: "Hier gibt es bereits eine Datei. Dem Paket fehlt die erforderliche Verifizierung, um zu bestätigen, dass es die alte Datei überschreiben kann.", fr: "Un fichier existe déjà ici. Le paquet n'a pas la vérification nécessaire pour confirmer qu'il peut écraser l'ancien fichier. Gardez l'ancien fichier et envoyez le journal aux responsables du gestionnaire.", it: "Un file esiste già qui. Il pacchetto manca la verifica necessaria per confermare che può sovrascrivere il vecchio file. Mantenere il vecchio file e inviare il registro ai manutentori del manager.", 'es-ES': "Un archivo ya existe aquí. El paquete carece de la verificación necesaria para confirmar que puede sobreescribir el archivo antiguo. Mantenga el archivo antiguo y enviar el registro a los usuarios del administrador.", ru: "Здесь уже есть файл. В пакете отсутствует проверка, необходимая для подтверждения того, что он может перезаписать старый файл. Сохраните старый файл и отправьте журнал администраторам.", pl: "Plik już tu istnieje. Pakiet nie posiada weryfikacji potrzebnej do potwierdzenia, że może nadpisać stary plik. Zachowaj stary plik i wyślij dziennik do opiekunów menedżera.", 'pt-BR': "Já existe um ficheiro aqui. O pacote carece da verificação necessária para confirmar que pode substituir o ficheiro antigo. Mantenha o ficheiro antigo e envie o registo para os mantenedores do gestor." }),
  installTargetOutsidePackage: withLocation({ 'zh-CN': '已有文件不在已确认的 MOD 安装目录内。请核对是否选对了安装包。如果仍失败，请保留文件并提供日志。', 'zh-TW': '現有檔案不在已確認的 MOD 安裝資料夾內。請確認是否選對安裝套件。如果仍失敗，請保留檔案並提供記錄。', en: 'The existing file is outside the confirmed MOD folder. Check that you selected the correct package. If it fails again, keep the file and share the log.', ko: '기존 파일이 확인된 MOD 설치 폴더 밖에 있습니다. 올바른 패키지를 선택했는지 확인하세요. 또 실패하면 파일을 보관하고 로그를 공유해 주세요.', ja: '既存ファイルが確認済みの MOD フォルダーの外にあります。選んだパッケージが正しいか確認してください。再度失敗する場合はファイルを残し、ログを共有してください。', de: "Die vorhandene Datei befindet sich außerhalb des bestätigten MOD-Ordners. Überprüfen Sie, ob Sie das richtige Paket ausgewählt haben. Wenn es erneut fehlschlägt, behalten Sie die Datei und teilen Sie das Protokoll.", fr: "Le fichier existant est à l'extérieur du dossier MOD confirmé. Vérifiez que vous avez sélectionné le bon paquet. Si il échoue à nouveau, conservez le fichier et partagez le journal.", it: "Il file esistente è al di fuori della cartella MOD confermata. Controlla che hai selezionato il pacchetto corretto. Se non riesce di nuovo, tieni il file e condividi il registro.", 'es-ES': "El archivo existente está fuera de la carpeta MOD confirmada. Compruebe que ha seleccionado el paquete correcto. Si falla de nuevo, mantenga el archivo y comparta el registro.", ru: "Существующий файл находится за пределами подтвержденной папки MOD. Проверьте, что вы выбрали правильный пакет. Если он снова выйдет из строя, сохраните файл и поделитесь журналом.", pl: "Istniejący plik znajduje się poza potwierdzonym folderem MOD. Sprawdź, czy wybrałeś właściwy pakiet. Jeśli nie uda się ponownie, zachowaj plik i udostępnij dziennik.", 'pt-BR': "O ficheiro existente está fora da pasta MOD confirmada. Verifique se seleccionou o pacote correcto. Se falhar de novo, mantenha o ficheiro e partilhe o registo." }),
  installTargetMapProtected: withLocation({ 'zh-CN': '这个位置由地图管理功能保留，管理器已阻止修改。请刷新地图列表，核对相关地图后再试。', 'zh-TW': '這個位置由地圖管理功能保留，管理器已阻止修改。請重新整理地圖清單，確認相關地圖後再試。', en: 'Map management reserves this location, so the manager blocked the change. Refresh the map list, check the relevant maps, and try again.', ko: '맵 관리 기능에서 사용하는 위치를 보호하기 위해 변경을 차단했습니다. 맵 목록을 새로 고치고 관련 맵을 확인한 뒤 다시 시도하세요.', ja: 'この場所はマップ管理用に確保されているため、変更を止めました。マップ一覧を更新して関連するマップを確認し、再試行してください。', de: "Die Kartenverwaltung reserviert diesen Speicherort, so dass der Manager die Änderung blockiert hat. Aktualisieren Sie die Kartenliste, überprüfen Sie die entsprechenden Karten und versuchen Sie es erneut.", fr: "La gestion des cartes se réserve cet emplacement, donc le gestionnaire a bloqué le changement. Rafraîchir la liste des cartes, vérifier les cartes pertinentes, et essayer à nouveau.", it: "La gestione della mappa si riserva questa posizione, quindi il gestore ha bloccato la modifica. Rifiutare l'elenco della mappa, controllare le mappe pertinenti, e riprovare.", 'es-ES': "La gestión de mapas se reserva esta ubicación, por lo que el administrador bloqueó el cambio. Refresh la lista de mapas, verifique los mapas pertinentes, e inténtelo de nuevo.", ru: "Управление картами резервирует это местоположение, поэтому менеджер заблокировал изменение. Обновите список карт, проверьте соответствующие карты и попробуйте еще раз.", pl: "Zarządzanie mapą rezerwuje to miejsce, więc menedżer zablokował zmianę. Odśwież listę map, sprawdź odpowiednie mapy i spróbuj ponownie.", 'pt-BR': "O gerenciamento do mapa reserva este local, de modo que o gerenciador bloqueou a alteração. Atualizar a lista de mapas, verificar os mapas relevantes e tentar novamente." }),
  installTargetMapRecordsUnreadable: withLocation({ 'zh-CN': '无法核对地图插件记录，因此不能确认这个位置是否由地图使用。请刷新地图列表后再试。如果仍失败，请提供日志。', 'zh-TW': '無法核對地圖外掛記錄，因此無法確認這個位置是否由地圖使用。請重新整理地圖清單後再試。如果仍失敗，請提供記錄。', en: 'The manager could not verify the map plugin records to check whether a map uses this location. Refresh the map list and retry. If it fails again, share the log.', ko: '맵 플러그인 기록을 확인하지 못해 맵에서 이 위치를 사용하는지 알 수 없습니다. 맵 목록을 새로 고친 뒤 다시 시도하세요. 또 실패하면 로그를 공유해 주세요.', ja: 'マップのプラグイン記録を照合できず、この場所をマップが使用しているか確認できません。一覧を更新して再試行してください。再度失敗する場合はログを共有してください。', de: "Der Manager konnte die Karten-Plugin-Einträge nicht überprüfen, um zu überprüfen, ob eine Karte diesen Speicherort verwendet.", fr: "Le gestionnaire n'a pas pu vérifier les enregistrements du plugin de la carte pour vérifier si une carte utilise cet emplacement. Rafraîchir la liste de la carte et réessayer. Si elle échoue encore, partagez le journal.", it: "Il gestore non è in grado di verificare i record di mappa del plugin per verificare se una mappa utilizza questa posizione.Rifiutare l'elenco della mappa e riprovare. Se non riesce di nuovo, condividere il registro.", 'es-ES': "El administrador no pudo verificar los registros de plugins del mapa para comprobar si un mapa utiliza esta ubicación. Reiniciar la lista de mapas y reingresar. Si falla de nuevo, compartir el registro.", ru: "Менеджер не смог проверить записи плагина карты, чтобы проверить, использует ли карта это местоположение. Обновить список карт и повторить. Если он снова выйдет из строя, поделитесь журналом.", pl: "Menedżer nie mógł zweryfikować rekordów wtyczki mapy, aby sprawdzić, czy mapa używa tej lokalizacji. Odśwież listę map i ponownie spróbować. Jeśli nie uda się ponownie, udostępnij log.", 'pt-BR': "O gestor não pôde verificar os registos de 'plugins' do mapa para verificar se um mapa usa esta localização. Actualizar a lista de mapas e tentar novamente. Se falhar novamente, partilhe o registo." }),
  installBundleNotDeclared: withLocation({ 'zh-CN': '新安装包的配置没有声明可以替换这个随包文件。请核对所选版本，或将日志发给仓库源维护者。', 'zh-TW': '新安裝套件的設定未宣告可取代這個隨套件檔案。請確認所選版本，或將記錄傳給來源維護者。', en: 'The new package configuration does not authorize replacing this bundled file. Check the selected version or send the log to the repository maintainer.', ko: '새 설치 패키지 설정에 이 구성 파일을 교체할 수 있다는 정보가 없습니다. 선택한 버전을 확인하거나 저장소 유지보수 담당자에게 로그를 보내 주세요.', ja: '新しいパッケージの設定には、この同梱ファイルを置き換える宣言がありません。選んだバージョンを確認するか、リポジトリのメンテナーにログを送ってください。', de: "Die neue Paketkonfiguration autorisiert nicht das Ersetzen dieser gebündelten Datei. Überprüfen Sie die ausgewählte Version oder senden Sie das Protokoll an den Repository Maintainer.", fr: "La nouvelle configuration du paquet n'autorise pas le remplacement de ce fichier groupé. Vérifiez la version sélectionnée ou envoyez le journal au responsable du dépôt.", it: "La nuova configurazione del pacchetto non autorizza la sostituzione di questo file in bundle. Controlla la versione selezionata o invia il registro al manutentore del repository.", 'es-ES': "La nueva configuración del paquete no autoriza la sustitución de este archivo agrupado. Compruebe la versión seleccionada o enviar el registro al encargado del repositorio.", ru: "Новая конфигурация пакета не разрешает замену этого пакетного файла. Проверьте выбранную версию или отправьте журнал в хранилище.", pl: "Nowa konfiguracja pakietów nie pozwala na wymianę tego pliku. Zaznacz wybraną wersję lub wyślij dziennik do opiekuna repozytorium.", 'pt-BR': "A nova configuração do pacote não autoriza a substituição deste arquivo empacotado. Verifique a versão selecionada ou envie o log para o mantenedor do repositório." }),
  installBundleMultipleMatches: withLocation({ 'zh-CN': '有多份文件与这个位置的文件匹配，无法确定该用哪一份。请核对所选版本，并将日志发给管理器维护者。', 'zh-TW': '有多份檔案與這個位置的檔案相符，無法確定要使用哪一份。請確認所選版本，並將記錄傳給管理器維護者。', en: 'More than one file matches, so the manager cannot select the right one for this location. Check the selected version and send the log to the manager’s maintainers.', ko: '이 위치에 맞는 파일이 여러 개 있어 사용할 파일을 결정할 수 없습니다. 선택한 버전을 확인하고 관리자 앱의 유지보수 담당자에게 로그를 보내 주세요.', ja: 'この場所に対応するファイルが複数あるため、使用するファイルを選べません。選んだバージョンを確認し、ログを管理アプリのメンテナーに送ってください。', de: "Mehr als eine Datei stimmt überein, so dass der Manager nicht die richtige für diesen Speicherort auswählen kann. Überprüfen Sie die ausgewählte Version und senden Sie das Protokoll an die Betreuer des Managers.", fr: "Plus d'un fichier correspond, donc le gestionnaire ne peut pas sélectionner le bon pour cet emplacement. Vérifiez la version sélectionnée et envoyez le journal aux responsables du gestionnaire.", it: "Più di un file corrisponde, quindi il manager non può selezionare quello giusto per questa posizione. Controllare la versione selezionata e inviare il registro ai manutentori del manager.", 'es-ES': "Más de un archivo coincide, por lo que el administrador no puede seleccionar el correcto para esta ubicación. Compruebe la versión seleccionada y enviar el registro a los usuarios del administrador.", ru: "Более чем один файл совпадает, поэтому менеджер не может выбрать правильный для этого места.Проверить выбранную версию и отправить журнал администраторам.", pl: "Więcej niż jeden plik pasuje, więc menedżer nie może wybrać odpowiedniego dla tej lokalizacji. Sprawdź wybraną wersję i wyślij dziennik do opiekunów menedżera.", 'pt-BR': "Mais de um ficheiro corresponde, pelo que o gestor não pode seleccionar o local certo para este local. Verifique a versão seleccionada e envie o registo para os mantenedores do gestor." }),
  installBundlePathChanged: withLocation({ 'zh-CN': '新包中对应的随包文件使用了不同的安装路径。请核对所选版本。如果仍失败，请保留现有文件并提供日志。', 'zh-TW': '新套件中對應的隨套件檔案使用不同的安裝路徑。請確認所選版本。如果仍失敗，請保留現有檔案並提供記錄。', en: 'The corresponding file in the new package uses a different installation path. Check the selected version. If it fails again, keep the existing files and share the log.', ko: '새 패키지의 해당 파일이 다른 설치 경로를 사용합니다. 선택한 버전을 확인하세요. 또 실패하면 기존 파일을 보관하고 로그를 공유해 주세요.', ja: '新しいパッケージ内の対応ファイルは別の場所にインストールされます。選んだバージョンを確認してください。再度失敗する場合は既存ファイルを残し、ログを共有してください。', de: "Die entsprechende Datei im neuen Paket verwendet einen anderen Installationspfad. Überprüfen Sie die ausgewählte Version. Wenn sie erneut fehlschlägt, behalten Sie die vorhandenen Dateien und teilen Sie das Protokoll.", fr: "Le fichier correspondant dans le nouveau paquet utilise un chemin d'installation différent. Vérifiez la version sélectionnée. Si elle échoue à nouveau, conservez les fichiers existants et partagez le journal.", it: "Il file corrispondente nel nuovo pacchetto utilizza un percorso di installazione diverso. Controllare la versione selezionata. Se non riesce di nuovo, mantenere i file esistenti e condividere il registro.", 'es-ES': "El archivo correspondiente en el nuevo paquete utiliza una ruta de instalación diferente. Compruebe la versión seleccionada. Si falla de nuevo, mantenga los archivos existentes y comparta el registro.", ru: "Соответствующий файл в новом пакете использует другой путь установки. Проверьте выбранную версию. Если она снова выйдет из строя, сохраните существующие файлы и поделитесь журналом.", pl: "Odpowiedni plik w nowym pakiecie używa innej ścieżki instalacji. Zaznacz wybraną wersję. Jeśli nie uda się ponownie, zachowaj istniejące pliki i udostępnij dziennik.", 'pt-BR': "O arquivo correspondente no novo pacote usa um caminho de instalação diferente. Verifique a versão selecionada. Se falhar novamente, mantenha os arquivos existentes e compartilhe o registro." }),
  installBundlePluginMismatch: withLocation({ 'zh-CN': '新包里的插件与该位置已有的插件对不上。请核对是否选对了 MOD 和版本。如果仍失败，请保留文件并提供日志。', 'zh-TW': '新套件中的外掛與該位置現有的外掛不相符。請確認是否選對 MOD 和版本。如果仍失敗，請保留檔案並提供記錄。', en: 'The plugin in the new package does not match the existing plugin at this location. Check the selected MOD and version. If it fails again, keep the files and share the log.', ko: '새 패키지의 플러그인이 이 위치의 기존 플러그인과 일치하지 않습니다. 올바른 MOD와 버전을 선택했는지 확인하세요. 또 실패하면 파일을 보관하고 로그를 공유해 주세요.', ja: '新しいパッケージのプラグインが、この場所の既存プラグインと一致しません。選んだ MOD とバージョンを確認してください。再度失敗する場合はファイルを残し、ログを共有してください。', de: "Das Plugin im neuen Paket stimmt nicht mit dem vorhandenen Plugin an dieser Stelle überein. Überprüfen Sie die ausgewählte MOD und Version. Wenn es erneut fehlschlägt, behalten Sie die Dateien und teilen Sie das Protokoll.", fr: "Le plugin dans le nouveau paquet ne correspond pas au plugin existant à cet emplacement. Vérifiez le MOD et la version sélectionnée. S'il échoue à nouveau, conservez les fichiers et partagez le journal.", it: "Il plugin nel nuovo pacchetto non corrisponde al plugin esistente in questa posizione. Controllare il MOD e la versione selezionata. Se non riesce di nuovo, mantenere i file e condividere il registro.", 'es-ES': "El plugin en el nuevo paquete no coincide con el plugin existente en esta ubicación. Compruebe el MOD seleccionado y la versión. Si falla de nuevo, mantenga los archivos y comparta el registro.", ru: "Плагин в новом пакете не соответствует существующему плагину в этом месте. Проверьте выбранный MOD и версию. Если он снова выйдет из строя, сохраните файлы и поделитесь журналом.", pl: "Wtyczka w nowym pakiecie nie pasuje do istniejącej wtyczki w tej lokalizacji. Sprawdź wybraną wersję MOD i. Jeśli nie powiedzie się ponownie, zachowaj pliki i udostępnij dziennik.", 'pt-BR': "O 'plugin' no novo pacote não corresponde ao 'plugin' existente neste local. Verifique o MOD e a versão seleccionadas. Se falhar de novo, mantenha os ficheiros e partilhe o registo." }),
  installTargetPluginIdentityUnknown: withLocation({ 'zh-CN': '管理器没能核对新旧文件的插件身份，无法确认能否替换。请保留现有文件，核对所选版本。如果仍失败，请提供日志。', 'zh-TW': '管理器未能核對新舊檔案的外掛身分，無法確認能否取代。請保留現有檔案，確認所選版本。如果仍失敗，請提供記錄。', en: 'The manager could not compare the plugin identities of the old and new files to verify the replacement. Keep the existing file and check the selected version. If it fails again, share the log.', ko: '기존 파일과 새 파일의 플러그인 정보를 비교할 수 없어 교체 가능 여부를 확인하지 못했습니다. 기존 파일을 보관하고 선택한 버전을 확인하세요. 또 실패하면 로그를 공유해 주세요.', ja: '新旧ファイルのプラグイン識別情報を照合できず、置き換えられるか確認できません。既存ファイルを残し、選んだバージョンを確認してください。再度失敗する場合はログを共有してください。', de: "Der Manager konnte die Plugin-Identitäten der alten und neuen Dateien nicht vergleichen, um den Ersatz zu überprüfen. Behalten Sie die vorhandene Datei und überprüfen Sie die ausgewählte Version.", fr: "Le gestionnaire n'a pas pu comparer les identités des plugins des anciens et des nouveaux fichiers pour vérifier le remplacement. Gardez le fichier existant et vérifiez la version sélectionnée. S'il échoue à nouveau, partagez le journal.", it: "Il manager non poteva confrontare le identità dei plugin dei vecchi e nuovi file per verificare la sostituzione. Mantenere il file esistente e controllare la versione selezionata. Se non riesce di nuovo, condividere il registro.", 'es-ES': "El administrador no pudo comparar las identidades del plugin de los archivos antiguos y nuevos para verificar el reemplazo. Mantenga el archivo existente y verifique la versión seleccionada. Si falla de nuevo, comparta el registro.", ru: "Менеджер не смог сравнить идентификаторы плагинов старых и новых файлов для проверки замены. Сохранить существующий файл и проверить выбранную версию. Если он снова выйдет из строя, поделитесь журналом.", pl: "Menedżer nie mógł porównać tożsamości wtyczki starych i nowych plików, aby zweryfikować wymianę. Zachowaj istniejący plik i sprawdź wybraną wersję. Jeśli nie uda się ponownie, udostępnij dziennik.", 'pt-BR': "O gestor não conseguiu comparar as identidades dos 'plugins' dos ficheiros antigos e novos para verificar a substituição. Mantenha o ficheiro existente e verifique a versão seleccionada. Se falhar de novo, partilhe o registo." }),
  installBundleFileDiffers: withLocation({ 'zh-CN': '这个随包辅助文件与新安装包里的内容不同，管理器无法确认可以覆盖。请保留现有文件，并将日志发给管理器维护者。', 'zh-TW': '此隨套件輔助檔案與新安裝套件中的內容不同，管理器無法確認能否覆寫。請保留現有檔案，並將記錄傳給管理器維護者。', en: 'This bundled helper file differs from the copy in the new package, so the manager could not verify the overwrite. Keep the existing file and send the log to the manager’s maintainers.', ko: '이 구성 파일이 새 설치 패키지의 파일과 내용이 달라 덮어쓸 수 있는지 확인하지 못했습니다. 기존 파일을 보관하고 관리자 앱의 유지보수 담당자에게 로그를 보내 주세요.', ja: 'この同梱の補助ファイルは新しいパッケージ内のファイルと内容が異なるため、上書きできるか確認できません。既存ファイルを残し、ログを管理アプリのメンテナーに送ってください。', de: "Diese gebündelte Helferdatei unterscheidet sich von der Kopie im neuen Paket, so dass der Manager die Überschreibung nicht überprüfen konnte.", fr: "Ce fichier d'aide groupé diffère de la copie du nouveau paquet, de sorte que le gestionnaire n'a pas pu vérifier l'écrasement. Gardez le fichier existant et envoyez le journal aux responsables du gestionnaire.", it: "Questo file helper in bundle differisce dalla copia nel nuovo pacchetto, in modo che il manager non poteva verificare la sovrascrittura. Mantenere il file esistente e inviare il registro ai manutentori del manager.", 'es-ES': "Este archivo de ayudantes agrupados difiere de la copia en el nuevo paquete, por lo que el administrador no pudo verificar la sobreescritura. Mantenga el archivo existente y enviar el registro a los usuarios del administrador.", ru: "Этот пакетный файл-помощник отличается от копии в новом пакете, поэтому менеджер не мог проверить перезапись.Сохранить существующий файл и отправить журнал администраторам.", pl: "Ten plik pomocniczy w pakiecie różni się od kopii w nowym pakiecie, więc menedżer nie mógł zweryfikować nadpisania. Zachować istniejący plik i wysłać dziennik do opiekunów menedżera.", 'pt-BR': "Este ficheiro de ajuda agrupado difere da cópia do novo pacote, pelo que o gestor não pôde verificar a sobreposição. Mantenha o ficheiro existente e envie o registo para os mantenedores do gestor." }),
  installRecordUnreadable: withLocation({ 'zh-CN': '管理器无法读取这份安装清单。请检查管理器数据目录的访问权限后重试。', 'zh-TW': '管理器無法讀取這份安裝清單。請檢查管理器資料資料夾的存取權限後再試。', en: 'The manager could not read this installation manifest. Check access permissions for the manager’s data folder and retry.', ko: '관리자 앱이 이 설치 명세를 읽을 수 없습니다. 관리자 앱의 데이터 폴더 접근 권한을 확인한 뒤 다시 시도하세요.', ja: 'このインストール記録を読み取れません。管理アプリのデータフォルダーのアクセス権を確認し、再試行してください。', de: "Der Manager konnte dieses Installationsmanifest nicht lesen. Überprüfen Sie die Zugriffsberechtigungen für den Datenordner des Managers und versuchen Sie es erneut.", fr: "Le gestionnaire n'a pas pu lire ce manifeste d'installation. Vérifiez les autorisations d'accès pour le dossier de données du gestionnaire et réessayez.", it: "Il gestore non poteva leggere questo manifesto di installazione. Controllare le autorizzazioni di accesso per la cartella dati del gestore e riprovare.", 'es-ES': "El administrador no pudo leer este manifiesto de instalación. Compruebe los permisos de acceso para la carpeta de datos y reingreso del administrador.", ru: "Менеджер не мог прочитать этот установочный манифест. Проверьте разрешения доступа к папке данных менеджера и повторите.", pl: "Menedżer nie mógł odczytać tego manifestu instalacyjnego. Sprawdź uprawnienia dostępu do folderu danych menedżera i ponownie spróbować.", 'pt-BR': "O gestor não conseguiu ler este manifesto de instalação. Verifique as permissões de acesso para a pasta de dados do gestor e tente novamente." }),
  installRecordInvalid: withLocation({ 'zh-CN': '这份安装清单的格式无效，无法用于核对旧文件。请保留清单原件，并将日志发给管理器维护者。', 'zh-TW': '這份安裝清單的格式無效，無法用於確認舊檔案。請保留清單原件，並將記錄傳給管理器維護者。', en: 'This installation manifest is invalid, so the manager cannot use it to verify the old files. Keep the original manifest and send the log to the manager’s maintainers.', ko: '이 설치 명세의 형식이 올바르지 않아 기존 파일을 확인할 수 없습니다. 명세 원본을 보관하고 관리자 앱의 유지보수 담당자에게 로그를 보내 주세요.', ja: 'このインストール記録の形式が無効で、既存ファイルを照合できません。記録の原本を残し、ログを管理アプリのメンテナーに送ってください。', de: "Dieses Installationsmanifest ist ungültig, so dass der Manager es nicht verwenden kann, um die alten Dateien zu verifizieren.Behalten Sie das Originalmanifest und senden Sie das Protokoll an die Betreuer des Managers.", fr: "Ce manifeste d'installation est invalide, de sorte que le gestionnaire ne peut pas l'utiliser pour vérifier les anciens fichiers. Gardez le manifeste original et envoyez le journal aux responsables du gestionnaire.", it: "Questo manifesto di installazione non è valido, quindi il gestore non può utilizzarlo per verificare i vecchi file. Mantenere il manifesto originale e inviare il registro ai manutentori del gestore.", 'es-ES': "Este manifiesto de instalación es inválido, por lo que el administrador no puede utilizarlo para verificar los archivos antiguos. Mantenga el manifiesto original y envíe el registro a los usuarios del administrador.", ru: "Этот установочный манифест недействителен, поэтому менеджер не может использовать его для проверки старых файлов.Сохранить первоначальный манифест и отправить журнал администраторам.", pl: "Ten manifest instalacji jest nieprawidłowy, więc menedżer nie może go użyć do weryfikacji starych plików. Zachowaj oryginalny manifest i wyślij dziennik do opiekunów menedżera.", 'pt-BR': "Este manifesto de instalação é inválido, pelo que o gestor não o pode usar para verificar os ficheiros antigos. Mantenha o manifesto original e envie o registo para os mantenedores do gestor." }),
  installRecordExists: withLocation({ 'zh-CN': '保存新安装清单的位置已被占用。请刷新列表后重试。如果仍失败，请保留现有清单并提供日志。', 'zh-TW': '儲存新安裝清單的位置已被占用。請重新整理清單後再試。如果仍失敗，請保留現有安裝清單並提供記錄。', en: 'The location for the new installation manifest is already occupied. Refresh the list and retry. If it fails again, keep the existing manifest and share the log.', ko: '새 설치 명세를 저장할 위치가 이미 사용 중입니다. 목록을 새로 고친 뒤 다시 시도하세요. 또 실패하면 기존 명세를 보관하고 로그를 공유해 주세요.', ja: '新しいインストール記録の保存先が既に使用されています。一覧を更新して再試行してください。再度失敗する場合は既存の記録を残し、ログを共有してください。', de: "Der Ort für das neue Installationsmanifest ist bereits besetzt. Die Liste wird aktualisiert und erneut versucht. Wenn es erneut fehlschlägt, behalten Sie das vorhandene Manifest und teilen Sie das Protokoll.", fr: "L'emplacement du nouveau manifeste d'installation est déjà occupé. Rafraîchir la liste et réessayer. S'il échoue à nouveau, conservez le manifeste existant et partagez le journal.", it: "La posizione per il nuovo manifesto di installazione è già occupata. Rifiutare l'elenco e riprovare. Se fallisce di nuovo, mantenere il manifesto esistente e condividere il registro.", 'es-ES': "El lugar para el nuevo manifiesto de instalación ya está ocupado. Rechazar la lista y volver a entrar. Si falla de nuevo, mantenga el manifiesto existente y comparta el registro.", ru: "Место для нового манифеста установки уже занято. Обновите список и повторите. Если он снова выйдет из строя, сохраните существующий манифест и поделитесь журналом.", pl: "Lokalizacja nowego manifestu instalacji jest już zajęta. Odśwież listę i powtórz. Jeśli nie uda się ponownie, zachowaj istniejący manifest i udostępnij dziennik.", 'pt-BR': "A localização do novo manifesto de instalação já está ocupada. Atualizar a lista e tentar novamente. Se falhar novamente, mantenha o manifesto existente e compartilhe o registro." }),
  installTargetAliasesOrLink: withLocation({ 'zh-CN': '无法确认这个文件只由当前路径使用。请检查是否存在文件链接或大小写不同的同名文件。如果无法确认，请保留文件并提供日志。', 'zh-TW': '無法確認這個檔案只由目前路徑使用。請檢查是否有檔案連結或大小寫不同的同名檔案。如果無法確認，請保留檔案並提供記錄。', en: 'The manager could not verify that only this path refers to the file. Check for file links or names that differ only in case. If you cannot confirm, keep the file and share the log.', ko: '이 경로만 해당 파일을 가리키는지 확인하지 못했습니다. 파일 링크나 대소문자만 다른 이름이 있는지 확인하세요. 확인할 수 없다면 파일을 보관하고 로그를 공유해 주세요.', ja: 'このパスだけがファイルを参照しているか確認できません。ファイルへのリンクや、大文字と小文字だけが異なる同名ファイルを確認してください。判断できない場合はファイルを残し、ログを共有してください。', de: "Der Manager konnte nicht überprüfen, ob sich nur dieser Pfad auf die Datei bezieht. Überprüfen Sie nach Dateilinks oder Namen, die sich nur im Fall unterscheiden.", fr: "Le gestionnaire n'a pas pu vérifier que seul ce chemin se réfère au fichier. Vérifiez les liens de fichier ou les noms qui diffèrent seulement au cas où. Si vous ne pouvez pas confirmer, conservez le fichier et partagez le journal.", it: "Il manager non poteva verificare che solo questo percorso si riferisce al file. Controllare i collegamenti di file o i nomi che differiscono solo nel caso in cui non si può confermare, mantenere il file e condividere il registro.", 'es-ES': "El administrador no pudo verificar que sólo esta ruta se refiere al archivo. Compruebe los enlaces de archivos o nombres que difieren sólo en el caso. Si no puede confirmar, mantenga el archivo y comparta el registro.", ru: "Менеджер не мог проверить, что только этот путь относится к файлу. Проверьте наличие файловых ссылок или имен, которые отличаются только в том случае. Если вы не можете подтвердить, сохраните файл и поделитесь журналом.", pl: "Menedżer nie mógł sprawdzić, czy tylko ta ścieżka odnosi się do pliku. Sprawdź, czy linki do plików lub nazwy różnią się tylko w przypadku. Jeśli nie możesz potwierdzić, zatrzymaj plik i udostępnij dziennik.", 'pt-BR': "O gestor não pôde verificar que apenas esta localização se refere ao ficheiro. Verifique se existem links ou nomes que diferem apenas no caso. Se não conseguir confirmar, mantenha o ficheiro e partilhe o registo." }),
  installTargetVerificationChanged: withLocation({ 'zh-CN': '再次检查时，安装位置的文件状态与前一次核对结果不一致。请刷新列表，等其他文件操作完成后再试。', 'zh-TW': '重新檢查時，安裝位置的檔案狀態與上次確認結果不一致。請重新整理清單，等候其他檔案操作完成後再試。', en: 'The installation location no longer matches the earlier check. Refresh the list, wait for any other file operations to finish, and retry.', ko: '다시 검사했을 때 설치 위치가 이전 확인 결과와 일치하지 않았습니다. 목록을 새로 고치고 다른 파일 작업이 끝난 뒤 다시 시도하세요.', ja: 'インストール先が前回の確認結果と一致しません。一覧を更新し、他のファイル操作が終わってから再試行してください。', de: "Der Installationsort stimmt nicht mehr mit der vorherigen Überprüfung überein. Aktualisieren Sie die Liste, warten Sie, bis andere Dateioperationen abgeschlossen sind, und wiederholen Sie es erneut.", fr: "L'emplacement de l'installation ne correspond plus à la vérification précédente. Rafraîchir la liste, attendre que d'autres opérations de fichiers soient terminées, et réessayer.", it: "La posizione dell'installazione non corrisponde più al controllo precedente. Rifiutare l'elenco, attendere che altre operazioni di file finiscano e riprovano.", 'es-ES': "La ubicación de la instalación ya no coincide con el cheque anterior. Refrescar la lista, esperar a que cualquier otra operación de archivo termine, y reingrese.", ru: "Место установки больше не соответствует предыдущей проверке. Обновите список, дождитесь завершения любых других операций с файлами и повторите попытку.", pl: "Lokalizacja instalacji nie pasuje już do wcześniejszego sprawdzenia. Odśwież listę, poczekaj, aż wszystkie inne operacje plików się skończą i spróbuj ponownie.", 'pt-BR': "O local de instalação não corresponde mais à verificação anterior. Atualizar a lista, esperar que outras operações de arquivos terminem e tentar novamente." }),
  installTargetPathCollision: withLocation({ 'zh-CN': '这次方案中的两项文件操作使用了重叠的路径。请分开操作或重新生成方案。如果仍失败，请提供日志。', 'zh-TW': '這次方案中的兩項檔案操作使用了重疊的路徑。請分開操作或重新產生方案。如果仍失敗，請提供記錄。', en: 'Two file operations in this plan use overlapping paths. Try them separately or create a new plan. If it fails again, share the log.', ko: '이 계획의 두 파일 작업이 서로 겹치는 경로를 사용합니다. 작업을 따로 실행하거나 계획을 다시 만드세요. 또 실패하면 로그를 공유해 주세요.', ja: '今回の計画では 2 つのファイル操作のパスが重なっています。操作を分けるか、計画を作り直してください。再度失敗する場合はログを共有してください。', de: "Zwei Dateioperationen in diesem Plan verwenden überlappende Pfade. Probieren Sie sie separat aus oder erstellen Sie einen neuen Plan.", fr: "Deux opérations de fichiers dans ce plan utilisent des chemins de chevauchement. Essayez-les séparément ou créez un nouveau plan. S'il échoue à nouveau, partagez le journal.", it: "Due operazioni di file in questo piano utilizzano percorsi sovrapposti. Provali separatamente o crea un nuovo piano. Se non riesce di nuovo, condividi il registro.", 'es-ES': "Dos operaciones de archivos en este plan utilizan rutas superpuestas. Pruébalas por separado o crea un nuevo plan. Si falla de nuevo, comparta el registro.", ru: "Две файловые операции в этом плане используют перекрывающиеся пути. Попробуйте их отдельно или создайте новый план. Если он снова выйдет из строя, поделитесь журналом.", pl: "Dwa operacje plików w tym planie używają pokrywających się ścieżek. Spróbuj je oddzielnie lub utworzyć nowy plan. Jeśli nie uda się ponownie, udostępnij dziennik.", 'pt-BR': "Duas operações de ficheiros neste plano usam caminhos sobrepostos. Tente- os separadamente ou crie um novo plano. Se falhar de novo, partilhe o registo." }),
  installTargetResidueDiffers: withLocation({ 'zh-CN': '找不到可用来核对的旧版主插件，而且这个位置的旧文件与新包内容不同。请先备份旧文件，确认它的来源后再重试。', 'zh-TW': '找不到可供確認的舊版主要外掛，而且此處的舊檔案與新套件內容不同。請先備份舊檔案，確認來源後再試一次。', en: 'The manager could not find the old main plugin to check, and the file at this location differs from the new package. Back up the old file and verify where it came from before retrying.', ko: '확인에 필요한 이전 버전의 주 플러그인을 찾을 수 없고, 이 위치의 기존 파일은 새 패키지와 내용이 다릅니다. 기존 파일을 백업하고 출처를 확인한 뒤 다시 시도하세요.', ja: '確認に必要な旧版のメインプラグインが見つからず、この場所の既存ファイルは新しいパッケージの内容と異なります。既存ファイルをバックアップし、入手元を確認してから再試行してください。', de: "Der Manager konnte das alte Haupt-Plugin nicht finden, um es zu überprüfen, und die Datei an diesem Ort unterscheidet sich vom neuen Paket.", fr: "Le gestionnaire n'a pas pu trouver l'ancien plugin principal à vérifier, et le fichier à cet emplacement diffère du nouveau paquet. Sauvegarder l'ancien fichier et vérifier d'où il vient avant de réessayer.", it: "Il manager non poteva trovare il vecchio plugin principale da controllare, e il file in questa posizione differisce dal nuovo pacchetto.", 'es-ES': "El administrador no pudo encontrar el viejo plugin principal para comprobar, y el archivo en esta ubicación difiere del nuevo paquete. Retroceder el archivo antiguo y verificar de dónde vino antes de reintentar.", ru: "Менеджер не смог найти старый главный плагин для проверки, и файл в этом месте отличается от нового пакета. Резервное копирование старого файла и проверка, откуда он пришел до повторного использования.", pl: "Menedżer nie mógł znaleźć starej wtyczki głównej do sprawdzenia, a plik w tej lokalizacji różni się od nowego pakietu. Backup starego pliku i sprawdzić, skąd pochodzi przed ponowną próbą.", 'pt-BR': "O gerenciador não conseguiu encontrar o plug- in principal antigo para verificar, e o arquivo neste local difere do novo pacote. Faça backup do arquivo antigo e verifique de onde ele veio antes de tentar novamente." }),
}
